 31 | export function createSession(input: CreateSessionInput): Session {
 32 |   const now = Date.now();
 33 |   const session: Session = {
 34 |     id: randomUUID(),
 35 |     assignmentId: input.assignmentId,
 36 |     language: input.language,
 37 |     statement: input.statement,
 38 |     workdir: input.workdir,
