 53 | /** Look up a session by HintLab id or by the SDK's agent session id. */
 54 | export function getSession(id: string): Session | undefined {
 55 |   const direct = sessions.get(id);
 56 |   if (direct) return direct;
 57 |   const hintlabId = agentIdIndex.get(id);
