 65 | /** Record an event and broadcast it to every connected SSE client. */
 66 | export function emitEvent(session: Session, name: string, data: unknown): void {
 67 |   // Raw events are stored verbatim for server-side logs/debugging.
 68 |   const event: SessionEvent = { name, data, at: Date.now() };
 69 |   session.events.push(event);
 70 |   session.lastActiveAt = Date.now();
 71 | 
 72 |   // Only a sanitised allow-list of events ever reaches a client.
 73 |   const clientEvent = filterEvent(name, data);
 74 |   if (!clientEvent) return;
 75 | 
 76 |   for (const res of session.sseClients) {
 77 |     try {
 78 |       writeSse(res, clientEvent.name, clientEvent.data);
 79 |     } catch {
 80 |       /* client already gone */
 81 |     }
 82 |   }
 83 | }
