 85 | /** Set the session status (emits a `status` event on change). */
 86 | export function setStatus(session: Session, status: string): void {
 87 |   if (session.status === status) return;
 88 |   session.status = status;
 89 |   session.lastActiveAt = Date.now();
 90 |   emitEvent(session, "status", { status });
 91 | }
 92 | 
 93 | /** Register an SSE client and replay the buffered event history to it. */
 94 | export function addClient(session: Session, res: Response): void {
 95 |   session.sseClients.add(res);
 96 |   session.lastActiveAt = Date.now();
 97 |   // Replay is synchronous and single-threaded, so no event can be broadcast
 98 |   // between the snapshot below and the live broadcast that follows it. The
 99 |   // same sanitisation allow-list applied to live events is applied here.
100 |   for (const event of session.events) {
101 |     const clientEvent = filterEvent(event.name, event.data);
102 |     if (!clientEvent) continue;
103 |     try {
104 |       writeSse(res, clientEvent.name, clientEvent.data);
105 |     } catch {
106 |       break;
107 |     }
108 |   }
109 | }
110 | 
111 | export function removeClient(session: Session, res: Response): void {
112 |   session.sseClients.delete(res);
113 | }
114 | 
115 | export function recordHint(session: Session, hint: Hint): void {
116 |   session.hints.push(hint);
117 |   session.lastActiveAt = Date.now();
118 |   emitEvent(session, "hint", hint);
119 | }
120 | 
121 | /** Remove a session, close its clients, and delete its temp workdir. */
122 | export function deleteSession(id: string): void {
123 |   const session = getSession(id);
124 |   if (!session) return;
125 |   sessions.delete(session.id);
126 |   if (session.agentSessionId) agentIdIndex.delete(session.agentSessionId);
127 | 
128 |   for (const res of session.sseClients) {
129 |     try {
130 |       res.end();
131 |     } catch {
132 |       /* ignore */
133 |     }
134 |   }
135 |   session.sseClients.clear();
136 | 
137 |   if (session.workdir) {
138 |     try {
139 |       fs.rmSync(session.workdir, { recursive: true, force: true });
140 |     } catch {
141 |       /* best-effort */
142 |     }
143 |   }
144 | 
145 |   if (session.agentSessionId) {
146 |     try {
147 |       stopAgentHook?.(session.agentSessionId);
148 |     } catch {
149 |       /* ignore */
150 |     }
151 |   }
152 | }
153 | 
154 | /** Start the TTL cleanup loop. Unref'd so it never keeps the process alive. */
155 | export function startCleanupLoop(): void {
156 |   const timer = setInterval(() => {
157 |     const now = Date.now();
158 |     for (const session of [...sessions.values()]) {
159 |       if (now - session.lastActiveAt > SESSION_TTL_MS) {
160 |         deleteSession(session.id);
161 |       }
162 |     }
163 |   }, SESSION_CLEANUP_INTERVAL_MS);
164 |   timer.unref();
165 | }

