  1 | /**
  2 |  * Server-side SSE filtering for HintLab.
  3 |  *
  4 |  * This is the single choke point between the server's internal (raw) event
  5 |  * stream and what may reach a browser. The agent emits unguarded model output
  6 |  * (`agent_text`, `reasoning`, and tool inputs/outputs that carry model free
  7 |  * text). We only ever forward a small allow-list of event types, and for each
  8 |  * of those we emit a sanitised payload that can never contain the model's own
  9 |  * words or raw SDK/stack-trace messages.
 10 |  *
 11 |  * Raw events are still recorded in the session (see `sessions.ts`) for
 12 |  * server-side logs/debugging; this module governs only what is streamed.
 13 |  */
 14 | 
 15 | import { extractCommands } from "./allowlist";
 16 | 
 17 | /** Event types that may ever be forwarded to a client. */
 18 | const ALLOWED_EVENT_TYPES: ReadonlySet<string> = new Set([
 19 |   "test_results",
 20 |   "tool_call",
 21 |   "tool_result",
 22 |   "approval",
 23 |   "hint",
 24 |   "hint_status",
 25 |   "hint_rejected",
 26 |   "status",
 27 |   "error",
 28 |   "done",
 29 | ]);
 30 | 
 31 | /** The only tool names we surface in `tool_call` / `tool_result`. */
 32 | const TOOL_CALL_TOOLS = new Set(["run_commands", "read_files", "run_tests"]);
 33 | 
 34 | export interface ClientEvent {
 35 |   name: string;
 36 |   data: unknown;
 37 | }
 38 | 
 39 | function asRecord(data: unknown): Record<string, unknown> {
 40 |   return data && typeof data === "object" && !Array.isArray(data)
 41 |     ? (data as Record<string, unknown>)
 42 |     : {};
 43 | }
 44 | 
 45 | function asString(v: unknown): string {
 46 |   return typeof v === "string" ? v : "";
 47 | }
 48 | 
 49 | /** Trim a potentially long string to a short, single-line summary. */
 50 | function trimSummary(value: unknown, max = 200): string {
 51 |   const s = asString(value).replace(/\s+/g, " ").trim();
 52 |   if (s.length <= max) return s;
 53 |   return `${s.slice(0, max - 1)}…`;
 54 | }
 55 | 
 56 | /** Recover one or more file paths from any accepted read_files input shape. */
 57 | function extractReadFileNames(input: unknown): string[] {
 58 |   const out: string[] = [];
 59 |   const visit = (v: unknown): void => {
 60 |     if (typeof v === "string") {
 61 |       out.push(v);
 62 |       return;
 63 |     }
 64 |     if (Array.isArray(v)) {
 65 |       for (const item of v) visit(item);
 66 |       return;
 67 |     }
 68 |     if (v && typeof v === "object") {
 69 |       const o = v as Record<string, unknown>;
 70 |       const direct = o.path ?? o.filePath ?? o.file_path;
 71 |       if (typeof direct === "string") {
 72 |         out.push(direct);
 73 |         return;
 74 |       }
 75 |       if (o.files !== undefined) visit(o.files);
 76 |     }
 77 |   };
 78 |   visit(input);
 79 |   return out;
 80 | }
 81 | 
 82 | /** Just the basename, so we never leak absolute sandbox paths to the browser. */
 83 | function basename(p: string): string {
 84 |   const n = p.split(/[\\/]/).filter(Boolean).pop();
 85 |   return n ?? p;
 86 | }
 87 | 
 88 | /** A test-results payload safe to show: no sandboxDir, trimmed stderr. */
 89 | export function sanitizeTestResults(data: unknown): Record<string, unknown> {
 90 |   const d = asRecord(data);
 91 |   const tests = Array.isArray(d.tests) ? (d.tests as Array<Record<string, unknown>>) : [];
 92 |   return {
 93 |     assignmentId: d.assignmentId,
 94 |     build: d.build
 95 |       ? {
 96 |           ok: (d.build as Record<string, unknown>).ok,
 97 |           timedOut: (d.build as Record<string, unknown>).timedOut,
 98 |           signal: (d.build as Record<string, unknown>).signal,
 99 |           stderr: trimSummary((d.build as Record<string, unknown>).stderr, 400),
100 |         }
101 |       : null,
102 |     tests: tests.map((t) => ({
103 |       name: t.name,
104 |       input: asString(t.input),
105 |       expected: asString(t.expected),
106 |       got: asString(t.got),
107 |       stderr: trimSummary(t.stderr, 400),
108 |       exitCode: t.exitCode,
109 |       signal: t.signal,
110 |       timedOut: t.timedOut,
111 |       passed: t.passed,
112 |     })),
113 |     passed: d.passed,
114 |     failed: d.failed,
115 |     total: d.total,
116 |   };
117 | }
118 | 
119 | 
120 | function filterToolCall(data: unknown): ClientEvent | null {
121 |   const d = asRecord(data);
122 |   const toolName = asString(d.toolName);
123 |   if (!TOOL_CALL_TOOLS.has(toolName)) return null;
124 | 
125 |   if (toolName === "run_commands") {
126 |     const commands = extractCommands(d.input);
127 |     return { name: "tool_call", data: { toolName, command: commands[0] ?? "" } };
128 |   }
129 | 
130 |   if (toolName === "read_files") {
131 |     const names = extractReadFileNames(d.input).map(basename);
132 |     return { name: "tool_call", data: { toolName, file: names[0] ?? "" } };
133 |   }
134 | 
135 |   // run_tests (custom, hardened) — only ever carries an optional test name.
136 |   const input = asRecord(d.input);
137 |   return {
138 |     name: "tool_call",
139 |     data: { toolName, testName: typeof input.testName === "string" ? input.testName : null },
140 |   };
141 | }
142 | 
143 | function filterToolResult(data: unknown): ClientEvent | null {
144 |   const d = asRecord(data);
145 |   const toolName = asString(d.toolName);
146 | 
147 |   if (toolName === "run_commands") {
148 |     const output = d.output ?? d.error ?? "";
149 |     return { name: "tool_result", data: { toolName, output: trimSummary(output, 200) } };
150 |   }
151 | 
152 |   if (toolName === "run_tests") {
153 |     const result = asRecord(d.output);
154 |     const tests = Array.isArray(result.tests) ? (result.tests as Array<Record<string, unknown>>) : [];
155 |     return {
156 |       name: "tool_result",
157 |       data: {
158 |         toolName,
159 |         passed: result.passed,
160 |         failed: result.failed,
161 |         total: result.total,
162 |         build: result.build
163 |           ? {
164 |               ok: (result.build as Record<string, unknown>).ok,
165 |               stderr: trimSummary((result.build as Record<string, unknown>).stderr, 200),
166 |             }
167 |           : null,
168 |         tests: tests.map((t) => ({
169 |           name: t.name,
170 |           passed: t.passed,
171 |           got: asString(t.got),
172 |           expected: asString(t.expected),
173 |           signal: t.signal,
174 |           stderr: trimSummary(t.stderr, 200),
175 |         })),
176 |       },
177 |     };
178 |   }
179 | 
180 |   // read_files results are full file contents (student code) — drop them.
181 |   return null;
182 | }
183 | 
184 | function filterApproval(data: unknown): ClientEvent | null {
185 |   const d = asRecord(data);
186 |   const toolName = asString(d.toolName);
187 |   const commands = Array.isArray(d.commands) ? d.commands.map((c) => asString(c)) : [];
188 |   const allowed = d.allowed === true;
189 |   return {
190 |     name: "approval",
191 |     data: {
192 |       toolName,
193 |       command: commands[0] ?? "",
194 |       allowed,
195 |       reason: allowed
196 |         ? undefined
197 |         : toolName === "run_commands"
198 |           ? "Command blocked by allow-list"
199 |           : "Tool not allowed in HintLab",
200 |     },
201 |   };
202 | }
203 | 
204 | function filterHint(data: unknown): ClientEvent | null {
205 |   const d = asRecord(data);
206 |   return {
207 |     name: "hint",
208 |     data: { level: d.level, tag: d.tag, text: asString(d.text) },
209 |   };
210 | }
211 | 
212 | /** Map a guard rejection reason to a tiny, fixed category (never the text). */
213 | function hintRejectCategory(reason: unknown): string {
214 |   const r = asString(reason);
215 |   if (r === "wrong level") return "wrong level";
216 |   if (r === "empty hint") return "empty hint";
217 |   return "contained code";
218 | }
219 | 
220 | function filterHintRejected(data: unknown): ClientEvent | null {
221 |   const d = asRecord(data);
222 |   return {
223 |     name: "hint_rejected",
224 |     data: { level: d.level, reason: hintRejectCategory(d.reason) },
225 |   };
226 | }
227 | 
228 | function filterStatus(data: unknown): ClientEvent | null {
229 |   const d = asRecord(data);
230 |   if (typeof d.status === "string") return { name: "status", data: { status: d.status } };
231 |   return null;
232 | }
233 | 
234 | /** Turn a raw error into a short human line — never a stack trace / SDK text. */
235 | function friendlyError(data: unknown): string {
236 |   const raw = asString(asRecord(data).message);
237 |   if (/timed?\s*out|timeout|ETIMEDOUT/i.test(raw)) return "Tutor timed out, try again";
238 |   if (/allow-?list|forbidden token/i.test(raw)) return "Command blocked by allow-list";
239 |   if (/hint|rephrase/i.test(raw)) return "Hint blocked, asking the tutor to rephrase";
240 |   return "Something went wrong. Please try again.";
241 | }
