243 | /**
244 |  * Given a raw event, return the sanitised client event to stream, or `null` to
245 |  * drop it entirely. Applied to live events and to the replay of buffered past
246 |  * events, so the same contract holds for late joiners.
247 |  */
248 | export function filterEvent(rawName: string, rawData: unknown): ClientEvent | null {
249 |   if (!ALLOWED_EVENT_TYPES.has(rawName)) return null;
250 | 
251 |   switch (rawName) {
252 |     case "test_results":
253 |       return { name: "test_results", data: sanitizeTestResults(rawData) };
254 |     case "tool_call":
255 |       return filterToolCall(rawData);
256 |     case "tool_result":
257 |       return filterToolResult(rawData);
258 |     case "approval":
259 |       return filterApproval(rawData);
260 |     case "hint":
261 |       return filterHint(rawData);
262 |     case "hint_status":
263 |     case "hint_rejected":
264 |       return filterHintRejected(rawData);
265 |     case "status":
266 |       return filterStatus(rawData);
267 |     case "error":
268 |       return { name: "error", data: { message: friendlyError(rawData) } };
269 |     case "done": {
270 |       const d = asRecord(rawData);
271 |       return { name: "done", data: { reason: asString(d.reason) || "done" } };
272 |     }
273 |     default:
274 |       return null;
275 |   }
276 | }
277 | 
278 | /** The full allow-list of event types that may reach the client (for checks). */
279 | export const CLIENT_EVENT_TYPES: readonly string[] = [...ALLOWED_EVENT_TYPES];
